{
  "title": "The Rescue of the Hollow Crown",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A small band gathers at the edge of the ruined city.",
      "visual_description": "Four cloaked figures stand on a ridge at dusk overlooking a shattered skyline of broken towers and tilted spires, banners fluttering in the distance.",
      "characters": ["Maren the Pathfinder", "Cole the Scout", "Vesna the Spellwright", "Brogan the Steward"]
    },
    {
      "scene_number": 2,
      "caption": "Maren unrolls a map of the fallen capital.",
      "visual_description": "Close-up on a weathered parchment map weighted down with stones, Maren pointing toward a marked tower while the others lean in by lantern light.",
      "characters": ["Maren the Pathfinder", "Cole the Scout", "Vesna the Spellwright", "Brogan the Steward"]
    },
    {
      "scene_number": 3,
      "caption": "They approach the broken castle gates.",
      "visual_description": "Massive iron-banded gates hang askew off their hinges, ivy crawling across the stonework, the party silhouetted at the threshold.",
      "characters": ["Maren the Pathfinder", "Cole the Scout", "Vesna the Spellwright", "Brogan the Steward"]
    },
    {
      "scene_number": 4,
      "caption": "A frightened townsperson warns them away.",
      "visual_description": "An old woman in a shawl clutches a basket against a cracked wall, gesturing fearfully toward the inner city while Maren listens.",
      "characters": ["Maren the Pathfinder", "Goodwife Halla"]
    },
    {
      "scene_number": 5,
      "caption": "Cole scouts ahead through a collapsed market.",
      "visual_description": "Cole crouches low among overturned stalls and shattered pottery, peering around a splintered awning, dust drifting in slanted light.",
      "characters": ["Cole the Scout"]
    },
    {
      "scene_number": 6,
      "caption": "An armored patrol marches past in the rubble.",
      "visual_description": "Three black-plated soldiers with halberds tramp down a narrow street, banners stitched with a broken crown, while Cole presses flat against a doorway.",
      "characters": ["Cole the Scout", "Iron Patrol Captain"]
    },
    {
      "scene_number": 7,
      "caption": "The party regroups under a tattered royal banner.",
      "visual_description": "A faded crimson banner with a golden crown hangs from a half-collapsed archway; the four companions confer beneath it in hushed urgency.",
      "characters": ["Maren the Pathfinder", "Cole the Scout", "Vesna the Spellwright", "Brogan the Steward"]
    },
    {
      "scene_number": 8,
      "caption": "Rumors of a dragon stop them cold.",
      "visual_description": "A wild-eyed hermit in patched robes points to deep claw gouges along a stone wall, ash smeared into the cracks; the party stares uneasily.",
      "characters": ["Maren the Pathfinder", "Vesna the Spellwright", "Brogan the Steward", "Ash-Eyed Hermit"]
    },
    {
      "scene_number": 9,
      "caption": "Brogan dozes against a fountain while plans are made.",
      "visual_description": "A round, bearded man in rumpled official robes snores against a cracked marble fountain, scroll slipping from his hand, as Maren rolls her eyes.",
      "characters": ["Brogan the Steward", "Maren the Pathfinder"]
    },
    {
      "scene_number": 10,
      "caption": "They reach the foot of the cursed tower.",
      "visual_description": "A leaning black tower wreathed in pale green mist, faintly glowing runes pulsing along its base, the party craning their heads upward.",
      "characters": ["Maren the Pathfinder", "Cole the Scout", "Vesna the Spellwright", "Brogan the Steward"]
    },
    {
      "scene_number": 11,
      "caption": "Vesna deciphers the magic door's sigils.",
      "visual_description": "Vesna traces glowing blue runes on a massive obsidian door, her staff sparking with answering light, the others guarding her back.",
      "characters": ["Vesna the Spellwright", "Maren the Pathfinder", "Cole the Scout"]
    },
    {
      "scene_number": 12,
      "caption": "The door swings open onto a spiral stair.",
      "visual_description": "A yawning archway reveals a winding stone staircase lit by floating motes of light, dust curling around the party's boots as they step inside.",
      "characters": ["Maren the Pathfinder", "Cole the Scout", "Vesna the Spellwright", "Brogan the Steward"]
    },
    {
      "scene_number": 13,
      "caption": "They find the captive prince in a sigil-bound cell.",
      "visual_description": "A young man in tattered finery sits chained inside a circle of burning red runes at the tower's top, dawn light leaking through arrow slits.",
      "characters": ["Prince Idris", "Vesna the Spellwright", "Maren the Pathfinder"]
    },
    {
      "scene_number": 14,
      "caption": "Vesna breaks the binding circle.",
      "visual_description": "Vesna slams her staff down, scattering the rune-circle into harmless sparks; the prince stumbles free as Maren catches his arm.",
      "characters": ["Vesna the Spellwright", "Prince Idris", "Maren the Pathfinder"]
    },
    {
      "scene_number": 15,
      "caption": "Alarm horns sound across the ruined city.",
      "visual_description": "From a tower window, the group sees torches igniting in every street and armored patrols converging, horns flashing in the early light.",
      "characters": ["Maren the Pathfinder", "Cole the Scout", "Vesna the Spellwright", "Brogan the Steward", "Prince Idris"]
    },
    {
      "scene_number": 16,
      "caption": "They flee through twisted alleys toward the river.",
      "visual_description": "The party sprints through narrow rubble-strewn lanes, cloaks streaming, arrows striking sparks off the cobbles behind them.",
      "characters": ["Maren the Pathfinder", "Cole the Scout", "Vesna the Spellwright", "Brogan the Steward", "Prince Idris", "Iron Patrol Captain"]
    },
    {
      "scene_number": 17,
      "caption": "Cole leaps the broken span of the great bridge.",
      "visual_description": "A vast stone bridge yawns with a missing center section over a churning river; Cole vaults the gap with a rope, the others poised to follow.",
      "characters": ["Cole the Scout", "Maren the Pathfinder", "Vesna the Spellwright", "Brogan the Steward", "Prince Idris"]
    },
    {
      "scene_number": 18,
      "caption": "The rescued prince looks back at the burning skyline.",
      "visual_description": "On the far riverbank at sunrise, the five companions stand together as Prince Idris turns to watch smoke rise from the ruined capital behind them.",
      "characters": ["Prince Idris", "Maren the Pathfinder", "Cole the Scout", "Vesna the Spellwright", "Brogan the Steward"]
    }
  ]
}

